G=load()
def f(inp):
    H=len(inp); W=len(inp[0]); bg=inp[0][0]
    seeds=[(i,j,v) for i,row in enumerate(inp) for j,v in enumerate(row) if v!=bg]
    res=[[bg]*W for _ in range(H)]
    # orientation: strip perpendicular to how seeds are clustered; if isolated seed, extend freely
    cols_=set(j for _,j,_ in seeds); rows_=set(i for i,_,_ in seeds)
    if len(cols_)>1 and len(rows_)==1:  # horizontally spread -> vertical strips
        vert=True
    elif len(rows_)>1 and len(cols_)==1:  # vertically spread -> horizontal bands
        vert=False
    else:
        # single seed: pick orientation that covers >= half grid along strip axis; fallback full grid
        verts={True: 3/W, False: 3/H}
        vert=max(verts,key=lambda o: max(o,1-verts[o])) if any(verts[o]>=0.5 for o in verts) else True
    for sr,sc,sv in seeds:
        if vert:
            lo,hi=max(0,sc-1),min(W,sc+2)
            covers=(hi-lo)/W
            if covers<0.5:
                lo,hi=0,W-1
            for r in range(H):
                for c in range(lo,hi+1):
                    if (r+c+sr+sc)%2==0: res[r][c]=sv
        else:
            lo,hi=max(0,sr-1),min(H,sr+2)
            covers=(hi-lo)/H
            if covers<0.5:
                lo,hi=0,H-1
            for c in range(W):
                for r in range(lo,hi+1):
                    if (r+c+sr+sc)%2==0: res[r][c]=sv
    return res
